import { test, expect } from '@playwright/test';

test.describe('Table Sorting by Column Headers', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table');
  });

  test('should sort table by clicking column headers', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify initial sort order (should be default or unsorted)
    const rows = page.getByRole('row');
    const firstRow = rows.first();
    const lastRow = rows.last();
    const firstLastName = await firstRow.getByText().first().textContent();
    const lastLastName = await lastRow.getByText().first().textContent();
    expect(firstLastName).not.toBe(lastLastName);

    // Click 'Last Name' column header to sort
    const lastNameHeader = page.getByRole('columnheader', { name: /last name/i });
    await lastNameHeader.click();

    // Verify table is sorted by Last Name (A-Z)
    const sortedRows = page.getByRole('row');
    const sortedFirstRow = sortedRows.first();
    const sortedLastRow = sortedRows.last();
    const sortedFirstLastName = await sortedFirstRow.getByText().first().textContent();
    const sortedLastLastName = await sortedLastRow.getByText().first().textContent();
    expect(sortedFirstLastName).toBeLessThanOrEqual(sortedLastLastName);

    // Click 'Last Name' column header again to reverse sort (Z-A)
    await lastNameHeader.click();

    // Verify table is reverse sorted by Last Name (Z-A)
    const reverseSortedRows = page.getByRole('row');
    const reverseSortedFirstRow = reverseSortedRows.first();
    const reverseSortedLastRow = reverseSortedRows.last();
    const reverseSortedFirstLastName = await reverseSortedFirstRow.getByText().first().textContent();
    const reverseSortedLastLastName = await reverseSortedLastRow.getByText().first().textContent();
    expect(reverseSortedFirstLastName).toBeGreaterThanOrEqual(reverseSortedLastLastName);

    // Click 'First Name' column header to sort
    const firstNameHeader = page.getByRole('columnheader', { name: /first name/i });
    await firstNameHeader.click();

    // Verify table is sorted by First Name (A-Z)
    const finalSortedRows = page.getByRole('row');
    const finalFirstRow = finalSortedRows.first();
    const finalLastRow = finalSortedRows.last();
    const finalFirstLastName = await finalFirstRow.getByText().first().textContent();
    const finalLastLastName = await finalLastRow.getByText().first().textContent();
    expect(finalFirstLastName).toBeLessThanOrEqual(finalLastLastName);
  });

  test('should handle sorting with empty table', async ({ page }) => {
    // Navigate to empty table view
    await page.goto('/table?empty=true');

    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify empty state message is displayed
    const emptyMessage = page.getByText('No records found');
    await expect(emptyMessage).toBeVisible();

    // Verify no column headers are present
    const columnHeaders = page.getByRole('columnheader');
    await expect(columnHeaders).not.toBeVisible();

    // Verify no rows are present
    const rows = page.getByRole('row');
    const rowCount = await rows.count();
    expect(rowCount).toBe(0);

    // Attempt to click a column header (should not crash)
    const lastNameHeader = page.getByRole('columnheader', { name: /last name/i });
    if (await lastNameHeader.isVisibleEnabled()) {
      await lastNameHeader.click();
    }

    // Verify empty state message persists
    await expect(emptyMessage).toBeVisible();
  });
});
